"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4053],{6617(e){e.exports=JSON.parse('{"title":"\uc131\uacf5\uc740 \ubb38\uc11c\ud654\uc5d0\uc11c \ub098\uc628\ub2e4 & \uadf8\ub7fc\uc5d0\ub3c4 \ub9ac\uc561\ud2b8\uac00 \uc88b\uc740 \uc774\uc720","date":"2024-04-03","coverUrl":null,"html":"<h2 data-notion-block-id=\\"2f70a4af-48e7-4bd9-aa34-4cef4c094e88\\" id=\\"2f70a4af-48e7-4bd9-aa34-4cef4c094e88\\">\uc131\uacf5\uc740 \ubb38\uc11c\ud654\uc5d0\uc11c \ub098\uc628\ub2e4</h2><a href=\\"https://johnjago.com/great-docs/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://johnjago.com/great-docs/</a><p data-notion-block-id=\\"bee37e3b-1302-46b6-bd35-3d851d2e4276\\"><b>\uc2ec\uc724\uc12d</b>: \uae00\uc4f4\uc774\ub294 ESBuild\uc640 Redis\uc758 \uc608\uc2dc\ub97c \ub4e4\uba74\uc11c \uc124\uacc4 \uc6d0\uce59, \uc0ac\uc6a9\ubc95, \uc124\uacc4 \uad6c\uc870, \ubcc0\uacbd\uc810\uc744 \uc798 \ubb38\uc11c\ud654\ud55c \ub450 \uc624\ud508\uc18c\uc2a4\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc624\ud508\uc18c\uc2a4\uc5d0\uc11c \uc88b\uc740 \ubb38\uc11c\uac00 \uc911\uc694\ud55c \uc774\uc720\ub97c \uc18c\uac1c\ud558\uc9c0\ub9cc \ub2e4\ub978 \ubaa8\ub4e0 \ud504\ub85c\uc81d\ud2b8\uc5d0\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc788\ub294 \ub9d0\uc774\uae30 \ub54c\ubb38\uc5d0 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"37446aaf-a0e7-4dfe-937c-e9e06e3c6bec\\"><b>\uae40\ub300\uad00:</b> \uac1c\ubc1c\uc5d0 \uc788\uc5b4\uc11c \ubb38\uc11c\ud654\ub294 \uac16\ub294 \uc758\ubbf8\ub294 \ub9e4\uc6b0 \ud07d\ub2c8\ub2e4. \uac1c\ubc1c \uc790\uccb4\ub97c \ud63c\uc790\uc11c \ud558\ub294 \uacbd\uc6b0\ubcf4\ub2e4\ub294, \ub2e4\uc218\uac00 \ud611\uc5c5\ud558\ub294 \uacbd\uc6b0\uac00 \ub354 \ub9ce\uae30 \ub54c\ubb38\uc5d0 \ucf54\ub4dc\uc5d0 \ub300\ud55c \uc9c0\uc2dd\uc744 \uc11c\ub85c\uac00 \uc54c\uace0 \uc788\uc5b4\uc57c\ud569\ub2c8\ub2e4. \uac1c\ubc1c\uc790\ub77c\uba74 \uc870\uc9c1\uacfc \ud300\uc6d0\ub4e4\uc744 \uc704\ud574 \uc790\uc2e0\uc758 \uc9c0\uc2dd\uc744 \ubb38\uc11c\ud654\ud558\ub294 \uacbd\ud5d8\uc744 \ub9ce\uc774 \uc2dc\ub3c4\ud574\ubcf4\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"b0fa8093-7010-49bd-9e12-b95e81fcacef\\" id=\\"b0fa8093-7010-49bd-9e12-b95e81fcacef\\">React.memo\ub97c \ub354 \ube60\ub974\uac8c</h2><a href=\\"https://romgrk.com/posts/react-fast-memo/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://romgrk.com/posts/react-fast-memo/</a><p data-notion-block-id=\\"a6d3d387-26bc-4d12-9a21-44065f310bd3\\"><b>\uc2ec\uc724\uc12d</b>: <code>React.memo</code>\ub294 <code>Object.is</code>\uba54\uc18c\ub4dc\ub97c \ubc14\ud0d5\uc73c\ub85c \uc774\uc804 props\uc640 \ud604\uc7ac props\uac00 \uac19\uc740\uc9c0 \ube44\uad50\ud569\ub2c8\ub2e4. \uc791\uc131\uc790\ub294 V8\uc774\ub098 SpiderMonkey\uac19\uc740 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8 \uc5d4\uc9c4\uc758 \ub0b4\ubd80 \ucd5c\uc801\ud654\ub97c \uc9c4\ud589\ud558\uc5ec \uc131\ub2a5\uc744 \ub192\uc774\ub294 \uc2dc\ub3c4\ub97c \ud588\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 monomorphism\uc5d0 \ub300\ud55c \uce90\uc2f1\uc744 \uc801\uadf9\uc801\uc73c\ub85c \uc0ac\uc6a9\ud588\ub294\ub370, \uad00\uc2ec\uc774 \uc788\ub2e4\uba74 \ub450 \uae00(<a href=\\"https://mrale.ph/blog/2015/01/11/whats-up-with-monomorphism.html\\">\uc624\ub798\ub41c \uae00</a>, <a href=\\"https://www.builder.io/blog/monomorphic-javascript\\">\ucd5c\uc2e0 \uae00</a>)\uc744 \uc0b4\ud3b4\ubcf4\uc138\uc694.</p><h2 data-notion-block-id=\\"107fdcba-6988-4f8f-911f-c4980a640c7f\\" id=\\"107fdcba-6988-4f8f-911f-c4980a640c7f\\">TypeScript Intersection Type(<code>&#x26;</code>)\uc0ac\uc6a9\uc744 \uc904\uc5ec\ub77c</h2><a href=\\"https://www.totaltypescript.com/react-apps-ts-performance\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/react-apps-ts-performance</a><p data-notion-block-id=\\"04124f6c-9781-4ae6-94d1-e87e56ec8893\\"><b>\uc2ec\uc724\uc12d</b>: <code>type</code> \uacfc <code>intersection</code> \uc0ac\uc6a9 \ub300\uc2e0 <code>interface extends</code>\ub97c \uc0ac\uc6a9\ud558\ub77c\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. \uc774\uc720\ub294 \uc815\ud655\ud558\uac8c \ubaa8\ub974\uc9c0\ub9cc, TypeScript\uc758 Wiki\uc640 \uc2e4\uc81c Sentry\uc5d0\uc11c \ub098\uc654\ub358 \uc131\ub2a5 \uc774\uc288\ub97c \uadfc\uac70\ub85c <code>type</code> \uacfc <code>intersection</code> \uc0ac\uc6a9\uc774 \uc131\ub2a5 \uc774\uc288\uac00 \uc788\ub2e4\uace0 \ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"01b1bd77-dd3b-4be6-969c-3cb60cd36db1\\" id=\\"01b1bd77-dd3b-4be6-969c-3cb60cd36db1\\">\uadf8\ub7fc\uc5d0\ub3c4 \ub9ac\uc561\ud2b8\uac00 \uc88b\uc740 \uc774\uc720</h2><a href=\\"https://ejosh.co/de/2024/03/why-i-like-react-even-in-2024/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ejosh.co/de/2024/03/why-i-like-react-even-in-2024/</a><p data-notion-block-id=\\"74a0d65f-7765-4423-ae90-4e24419444b4\\"><b>\uc2ec\uc724\uc12d</b>: \ub2e4\ub978 \uae00\uc5d0 \ub300\ud55c \ubc18\ubc15\uc774\uc9c0\ub9cc, \uc591\ubc29\ud5a5 \ub370\uc774\ud130 \ubc14\uc778\ub529\uc774 \ud3fc\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294\ub370\uc5d0 \uc88b\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc \ubcf5\uc7a1\uc131\uacfc \ubd88\ubcc0\uc131\uc744 \uc9c0\ud0a4\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc774 \ubb38\uc81c\uac00 \ub420 \uc218\ub3c4 \uc788\uace0, JSX\ub294 \uc544\uc9c1 \uac15\ub825\ud558\ub2e4\ub77c\ub294 \uac83\uc744 \ubc14\ud0d5\uc73c\ub85c \uc544\uc9c1 \ub9ac\uc561\ud2b8\ub294 \uc88b\ub2e4\ub77c\ub294 \uac83\uc744 \uc8fc\uc7a5\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"db6b486a-ac4d-43cd-889c-7e41f5be3ec6\\" id=\\"db6b486a-ac4d-43cd-889c-7e41f5be3ec6\\">\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc758 \ucd94\ub860 \ubc29\uc2dd</h2><a href=\\"https://effectivetypescript.com/2024/03/24/flownodes/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://effectivetypescript.com/2024/03/24/flownodes/</a><p data-notion-block-id=\\"5d5cd1f5-8e2d-411d-a672-4e4755052813\\"><b>\uc2ec\uc724\uc12d</b>: TypeScript\uac00 \uc5b4\ub5bb\uac8c \ucd94\ub860\ud558\ub294\uc9c0 AST\uc640 \ucf54\ub4dc\ub97c \ud1b5\ud574\uc11c \uc124\uba85\ud569\ub2c8\ub2e4. \ubcc0\uc218\uc758 \ud0c0\uc785\uc744 \uc881\ud600\ub3c4 \ubcc0\uc218\ub97c \uc4f0\uc9c0 \uc54a\uc73c\uba74 \ucd94\ub860\uc744 \ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc5ec\ub7ec\uac00\uc9c0 \uad6c\ubb38\uc73c\ub85c \uc870\uac74\ubb38\uc744 \ub9e4\uc6b0 \ub9ce\uc774 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc2e0\uae30\ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"738ecb4b-eae9-4534-b05f-8bf0f4b8bb90\\" id=\\"738ecb4b-eae9-4534-b05f-8bf0f4b8bb90\\">CodePush\uac00 \uc0ac\ub77c\uc9d1\ub2c8\ub2e4.</h2><a href=\\"https://expo.dev/blog/how-to-replace-app-center-and-codepush\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://expo.dev/blog/how-to-replace-app-center-and-codepush</a><p data-notion-block-id=\\"da0e0d2c-e7df-4171-b5f8-6b7c37938d93\\"><b>\uc2ec\uc724\uc12d</b>: CodePush\uc758 \uacc4\uc2b9\uc790\uc778 Microsoft App Center\uac00 \ubb38\uc744 \ub2eb\uc2b5\ub2c8\ub2e4. \uadf8\ub85c \uc778\ud574 \ubc30\ud3ec\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\uae30\uc5d0 Expo\uce21\uc5d0\uc11c EAS\uc11c\ube44\uc2a4\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc788\uc5c8\ub358 Expo\uc5d0\uc11c\ub9cc \ube4c\ub4dc\ub418\ub358 \uc2dc\uc2a4\ud15c\uc5d0\uc11c \ubc97\uc5b4\ub0a0 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uac80\ud1a0\ud558\uace0 \uc77c\ubd80\ub97c EAS\uc640 \ud568\uaed8\ud574\ub3c4 \uad1c\ucc2e\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"abf1fc23-6dfe-4885-9fab-d672b2c4a5e3\\" id=\\"abf1fc23-6dfe-4885-9fab-d672b2c4a5e3\\">RN\uc758 \ubbf8\ub798(\ud76c\ub9dd\ud3b8)</h2><a href=\\"https://toss.tech/article/react-native-2024\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://toss.tech/article/react-native-2024</a><p data-notion-block-id=\\"c049527b-c37f-44a9-9099-8bdc9055a645\\"><b>\uc2ec\uc724\uc12d</b>: \uc7ac\ubc0c\ub294 RN \uc804\ud658 \uc18c\uc2dd\uc774 \ub4e4\ub824\uc640\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. React Native \ud300\uc5d0\uc11c New Architecture\uacfc Filpper, Hermes \ub4f1 \ub9ce\uc740 \ud234\uc744 \uc18c\uac1c\ud558\uba74\uc11c \ucc3d\ucc3d\ud55c \ubbf8\ub798\ub97c \ubcf4\uc5ec\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 \ud76c\ub9dd\ud3b8\uc774\ub77c \uc801\uc5b4\ub1a8\ub4ef\uc774 1\ubc84\uc804\uc774 \uc548 \ub418\uc5b4\uc11c \uc790\uc8fc \uad6c\uc870\uac00 \ubc14\ub00c\ub294 \ubb38\uc81c(\uc774\ub97c \ub3c4\uc640\uc8fc\ub294 <a href=\\"https://react-native-community.github.io/upgrade-helper/\\">\uc6f9\uc0ac\uc774\ud2b8</a>\uac00 \ub530\ub85c \uc788\uc74c), \ucd94\uc0c1\ud654\ub85c \uc778\ud574 \uad00\ub9ac\ud3ec\uc778\ud2b8\uac00 \ud558\ub098 \ub354 \ub298\uc5b4\ub0a8(Shopify\ub294 \ubd80\uc871\ud55c RN \ub9ac\uc18c\uc2a4\uc640 \uadf8 \uc0dd\ud0dc\uacc4\ub97c \uc9c1\uc811 \ucc44\uc6b0\uace0 \uc788\ub294 \uac83 \uac19\ub124\uc694, <a href=\\"https://shopify.engineering/react-native-future-mobile-shopify\\">1</a>, <a href=\\"https://shopify.engineering/migrating-our-largest-mobile-app-to-react-native\\">2</a>)\u2026 \ub4f1 \uc5ec\ub7ec\uac00\uc9c0 \ubb38\uc81c\ub97c \ub6ab\uc5b4\uc57c \ud558\uc8e0. \uc5b4\ub5bb\uac8c \ub09c\uad00\uc744 \ub6ab\uc744\uc9c0 \uad81\uae08\ud574\uc9c0\ub124\uc694 \ud83d\ude42. \uc5b8\uc81c\ub098 \uadf8\ub7ac\ub4ef\uc774 \uc804\ud658\uc5d0 <a href=\\"https://www.twopicode.com/articles/this-is-why-we-stopped-using-react-native/\\">\uc2e4\ud328\ud55c \uc0ac\ub840</a>\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"bc6cbd07-8d63-4062-b41b-f03e73aee9f8\\"></p>"}')}}]);